-- Road Platform backup
-- 2026-11-21 18:03:21

DROP TABLE IF EXISTS `admin_areas`;
CREATE TABLE `admin_areas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `level` enum('division','district','upazila','city_corporation','pourashava','union','ward') NOT NULL,
  `name_bn` varchar(150) NOT NULL,
  `name_en` varchar(150) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `admin_areas_parent_id_foreign` (`parent_id`),
  KEY `admin_areas_level_index` (`level`),
  CONSTRAINT `admin_areas_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `admin_areas` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5098 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `audit_events`;
CREATE TABLE `audit_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `actor_id` bigint(20) unsigned DEFAULT NULL,
  `action` varchar(50) NOT NULL,
  `target_type` varchar(30) NOT NULL,
  `target_id` varchar(40) NOT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`details`)),
  `ip_address` varchar(45) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `audit_events_actor_id_foreign` (`actor_id`),
  KEY `audit_events_target_type_target_id_index` (`target_type`,`target_id`),
  CONSTRAINT `audit_events_actor_id_foreign` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=259 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `authorities`;
CREATE TABLE `authorities` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name_bn` varchar(200) NOT NULL,
  `name_en` varchar(200) DEFAULT NULL,
  `type` enum('rhd','lged','city_corporation','pourashava','union_parishad','wasa','utility','other') NOT NULL,
  `admin_area_id` bigint(20) unsigned DEFAULT NULL,
  `public_phone` varchar(50) DEFAULT NULL,
  `public_email` varchar(150) DEFAULT NULL,
  `website` varchar(300) DEFAULT NULL,
  `source_url` varchar(500) DEFAULT NULL,
  `last_verified_at` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `authorities_admin_area_id_foreign` (`admin_area_id`),
  CONSTRAINT `authorities_admin_area_id_foreign` FOREIGN KEY (`admin_area_id`) REFERENCES `admin_areas` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `authority_contacts`;
CREATE TABLE `authority_contacts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `admin_area_id` bigint(20) unsigned NOT NULL,
  `authority_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `position` varchar(150) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `whatsapp` varchar(30) DEFAULT NULL,
  `status` enum('pending','approved','disabled') NOT NULL DEFAULT 'pending',
  `added_by` bigint(20) unsigned NOT NULL,
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `authority_contacts_authority_id_foreign` (`authority_id`),
  KEY `authority_contacts_added_by_foreign` (`added_by`),
  KEY `authority_contacts_approved_by_foreign` (`approved_by`),
  KEY `authority_contacts_admin_area_id_status_index` (`admin_area_id`,`status`),
  CONSTRAINT `authority_contacts_added_by_foreign` FOREIGN KEY (`added_by`) REFERENCES `users` (`id`),
  CONSTRAINT `authority_contacts_admin_area_id_foreign` FOREIGN KEY (`admin_area_id`) REFERENCES `admin_areas` (`id`),
  CONSTRAINT `authority_contacts_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `authority_contacts_authority_id_foreign` FOREIGN KEY (`authority_id`) REFERENCES `authorities` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `blocked_ips`;
CREATE TABLE `blocked_ips` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ip` varchar(45) NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `blocked_ips_ip_unique` (`ip`),
  KEY `blocked_ips_user_id_foreign` (`user_id`),
  KEY `blocked_ips_created_by_foreign` (`created_by`),
  CONSTRAINT `blocked_ips_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `blocked_ips_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache`;
CREATE TABLE `cache` (
  `key` varchar(255) NOT NULL,
  `value` mediumtext NOT NULL,
  `expiration` bigint(20) NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (
  `key` varchar(255) NOT NULL,
  `owner` varchar(255) NOT NULL,
  `expiration` bigint(20) NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(50) NOT NULL,
  `name_bn` varchar(100) NOT NULL,
  `name_en` varchar(100) NOT NULL,
  `sort` smallint(5) unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `categories_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `evidence`;
CREATE TABLE `evidence` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `report_id` bigint(20) unsigned DEFAULT NULL,
  `status_event_id` bigint(20) unsigned DEFAULT NULL,
  `observation_id` bigint(20) unsigned DEFAULT NULL,
  `uploader_id` bigint(20) unsigned NOT NULL,
  `public_path` varchar(500) NOT NULL,
  `private_path` varchar(500) DEFAULT NULL,
  `taken_at` timestamp NULL DEFAULT NULL,
  `moderation` enum('pending','approved','hidden') NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `private_disk` varchar(50) DEFAULT NULL,
  `public_disk` varchar(50) DEFAULT NULL,
  `hidden_at` timestamp NULL DEFAULT NULL,
  `hidden_by` bigint(20) unsigned DEFAULT NULL,
  `hidden_reason` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `evidence_report_id_foreign` (`report_id`),
  KEY `evidence_status_event_id_foreign` (`status_event_id`),
  KEY `evidence_uploader_id_foreign` (`uploader_id`),
  KEY `evidence_observation_id_index` (`observation_id`),
  KEY `evidence_moderation_idx` (`moderation`),
  CONSTRAINT `evidence_report_id_foreign` FOREIGN KEY (`report_id`) REFERENCES `reports` (`id`),
  CONSTRAINT `evidence_status_event_id_foreign` FOREIGN KEY (`status_event_id`) REFERENCES `status_events` (`id`),
  CONSTRAINT `evidence_uploader_id_foreign` FOREIGN KEY (`uploader_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(255) NOT NULL,
  `connection` varchar(255) NOT NULL,
  `queue` varchar(255) NOT NULL,
  `payload` longtext NOT NULL,
  `exception` longtext NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`),
  KEY `failed_jobs_connection_queue_failed_at_index` (`connection`,`queue`,`failed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fund_campaigns`;
CREATE TABLE `fund_campaigns` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `goal_amount` bigint(20) unsigned NOT NULL,
  `ends_at` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 0,
  `show_donors` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fund_donations`;
CREATE TABLE `fund_donations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `campaign_id` bigint(20) unsigned NOT NULL,
  `amount` bigint(20) unsigned NOT NULL,
  `currency` varchar(3) NOT NULL DEFAULT 'BDT',
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `gateway` varchar(30) NOT NULL DEFAULT 'manual',
  `tran_id` varchar(100) DEFAULT NULL,
  `invoice_id` varchar(64) DEFAULT NULL,
  `donor_name` varchar(120) DEFAULT NULL,
  `donor_contact` varchar(150) DEFAULT NULL,
  `show_name` tinyint(1) NOT NULL DEFAULT 0,
  `hide_amount` tinyint(1) NOT NULL DEFAULT 0,
  `is_manual` tinyint(1) NOT NULL DEFAULT 0,
  `note` text DEFAULT NULL,
  `recorded_by` bigint(20) unsigned DEFAULT NULL,
  `paid_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fund_donations_tran_id_unique` (`tran_id`),
  KEY `fund_donations_campaign_id_foreign` (`campaign_id`),
  KEY `fund_donations_status_index` (`status`),
  KEY `fund_donations_invoice_id_index` (`invoice_id`),
  CONSTRAINT `fund_donations_campaign_id_foreign` FOREIGN KEY (`campaign_id`) REFERENCES `fund_campaigns` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fund_expenses`;
CREATE TABLE `fund_expenses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `campaign_id` bigint(20) unsigned NOT NULL,
  `head_id` bigint(20) unsigned DEFAULT NULL,
  `amount` bigint(20) unsigned NOT NULL,
  `spent_on` date NOT NULL,
  `description` varchar(500) NOT NULL,
  `voucher_path` varchar(300) DEFAULT NULL,
  `voucher_disk` varchar(30) DEFAULT NULL,
  `voucher_mime` varchar(100) DEFAULT NULL,
  `recorded_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fund_expenses_campaign_id_foreign` (`campaign_id`),
  KEY `fund_expenses_head_id_foreign` (`head_id`),
  CONSTRAINT `fund_expenses_campaign_id_foreign` FOREIGN KEY (`campaign_id`) REFERENCES `fund_campaigns` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fund_expenses_head_id_foreign` FOREIGN KEY (`head_id`) REFERENCES `fund_heads` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fund_heads`;
CREATE TABLE `fund_heads` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `campaign_id` bigint(20) unsigned NOT NULL,
  `name` varchar(150) NOT NULL,
  `amount` bigint(20) unsigned NOT NULL DEFAULT 0,
  `sort` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fund_heads_campaign_id_foreign` (`campaign_id`),
  CONSTRAINT `fund_heads_campaign_id_foreign` FOREIGN KEY (`campaign_id`) REFERENCES `fund_campaigns` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `issue_authority_links`;
CREATE TABLE `issue_authority_links` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `issue_id` bigint(20) unsigned NOT NULL,
  `authority_id` bigint(20) unsigned NOT NULL,
  `state` enum('proposed','verified','disputed') NOT NULL DEFAULT 'proposed',
  `basis` text NOT NULL,
  `source_url` varchar(500) DEFAULT NULL,
  `linked_by` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `issue_authority_links_issue_id_foreign` (`issue_id`),
  KEY `issue_authority_links_authority_id_foreign` (`authority_id`),
  KEY `issue_authority_links_linked_by_foreign` (`linked_by`),
  CONSTRAINT `issue_authority_links_authority_id_foreign` FOREIGN KEY (`authority_id`) REFERENCES `authorities` (`id`),
  CONSTRAINT `issue_authority_links_issue_id_foreign` FOREIGN KEY (`issue_id`) REFERENCES `issues` (`id`),
  CONSTRAINT `issue_authority_links_linked_by_foreign` FOREIGN KEY (`linked_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `issue_follows`;
CREATE TABLE `issue_follows` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `issue_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `issue_follows_issue_id_user_id_unique` (`issue_id`,`user_id`),
  KEY `issue_follows_issue_id_index` (`issue_id`),
  KEY `issue_follows_user_id_index` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `issue_notifications`;
CREATE TABLE `issue_notifications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `issue_id` bigint(20) unsigned NOT NULL,
  `authority_contact_id` bigint(20) unsigned NOT NULL,
  `channel` varchar(20) NOT NULL,
  `status` varchar(20) NOT NULL,
  `sent_by` bigint(20) unsigned NOT NULL,
  `message` text DEFAULT NULL,
  `error` varchar(200) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `issue_notifications_sent_by_foreign` (`sent_by`),
  KEY `issue_notifications_issue_id_created_at_index` (`issue_id`,`created_at`),
  KEY `issue_notif_contact_idx` (`authority_contact_id`,`channel`,`created_at`),
  CONSTRAINT `issue_notifications_authority_contact_id_foreign` FOREIGN KEY (`authority_contact_id`) REFERENCES `authority_contacts` (`id`),
  CONSTRAINT `issue_notifications_issue_id_foreign` FOREIGN KEY (`issue_id`) REFERENCES `issues` (`id`),
  CONSTRAINT `issue_notifications_sent_by_foreign` FOREIGN KEY (`sent_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `issues`;
CREATE TABLE `issues` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `public_id` char(26) NOT NULL,
  `title` varchar(200) NOT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `lat` decimal(10,7) NOT NULL,
  `lng` decimal(10,7) NOT NULL,
  `road_name` varchar(200) DEFAULT NULL,
  `landmark` varchar(200) DEFAULT NULL,
  `admin_area_id` bigint(20) unsigned DEFAULT NULL,
  `progress_status` enum('reported','acknowledged','planned','work_started','completion_reported','repaired') NOT NULL DEFAULT 'reported',
  `verification_status` enum('unverified','community_confirmed','reviewed','verified') NOT NULL DEFAULT 'unverified',
  `disposition` enum('active','duplicate','rejected','referred','reopened') NOT NULL DEFAULT 'active',
  `duplicate_of_id` bigint(20) unsigned DEFAULT NULL,
  `reports_count` int(10) unsigned NOT NULL DEFAULT 0,
  `first_reported_at` timestamp NULL DEFAULT NULL,
  `last_activity_at` timestamp NULL DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `unpublished_at` timestamp NULL DEFAULT NULL,
  `unpublished_by` bigint(20) unsigned DEFAULT NULL,
  `unpublish_reason` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `issues_public_id_unique` (`public_id`),
  KEY `issues_category_id_foreign` (`category_id`),
  KEY `issues_admin_area_id_foreign` (`admin_area_id`),
  KEY `issues_duplicate_of_id_foreign` (`duplicate_of_id`),
  KEY `issues_lat_lng_index` (`lat`,`lng`),
  KEY `issues_disposition_progress_status_index` (`disposition`,`progress_status`),
  KEY `issues_published_at_index` (`published_at`),
  CONSTRAINT `issues_admin_area_id_foreign` FOREIGN KEY (`admin_area_id`) REFERENCES `admin_areas` (`id`),
  CONSTRAINT `issues_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `issues_duplicate_of_id_foreign` FOREIGN KEY (`duplicate_of_id`) REFERENCES `issues` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `total_jobs` int(11) NOT NULL,
  `pending_jobs` int(11) NOT NULL,
  `failed_jobs` int(11) NOT NULL,
  `failed_job_ids` longtext NOT NULL,
  `options` mediumtext DEFAULT NULL,
  `cancelled_at` int(11) DEFAULT NULL,
  `created_at` int(11) NOT NULL,
  `finished_at` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(255) NOT NULL,
  `payload` longtext NOT NULL,
  `attempts` smallint(5) unsigned NOT NULL,
  `reserved_at` int(10) unsigned DEFAULT NULL,
  `available_at` int(10) unsigned NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) NOT NULL,
  `batch` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `moderator_areas`;
CREATE TABLE `moderator_areas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `admin_area_id` bigint(20) unsigned NOT NULL,
  `granted_by` bigint(20) unsigned DEFAULT NULL,
  `revoked_at` timestamp NULL DEFAULT NULL,
  `revoked_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `moderator_areas_admin_area_id_foreign` (`admin_area_id`),
  KEY `moderator_areas_granted_by_foreign` (`granted_by`),
  KEY `moderator_areas_revoked_by_foreign` (`revoked_by`),
  KEY `moderator_areas_user_id_revoked_at_index` (`user_id`,`revoked_at`),
  CONSTRAINT `moderator_areas_admin_area_id_foreign` FOREIGN KEY (`admin_area_id`) REFERENCES `admin_areas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `moderator_areas_granted_by_foreign` FOREIGN KEY (`granted_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `moderator_areas_revoked_by_foreign` FOREIGN KEY (`revoked_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `moderator_areas_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `observations`;
CREATE TABLE `observations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `issue_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `type` enum('still_exists','got_worse','partially_fixed','fixed') NOT NULL,
  `note` varchar(500) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `observations_user_id_foreign` (`user_id`),
  KEY `observations_issue_id_created_at_index` (`issue_id`,`created_at`),
  CONSTRAINT `observations_issue_id_foreign` FOREIGN KEY (`issue_id`) REFERENCES `issues` (`id`),
  CONSTRAINT `observations_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `otp_codes`;
CREATE TABLE `otp_codes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `phone` varchar(20) NOT NULL,
  `code_hash` varchar(255) NOT NULL,
  `attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `expires_at` timestamp NOT NULL,
  `used_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `otp_codes_phone_index` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `page_views`;
CREATE TABLE `page_views` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `path` varchar(191) NOT NULL,
  `referrer` varchar(191) DEFAULT NULL,
  `vhash` char(16) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `page_views_date_path_index` (`date`,`path`),
  KEY `page_views_date_index` (`date`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pages`;
CREATE TABLE `pages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(60) NOT NULL,
  `title_bn` varchar(150) NOT NULL,
  `title_en` varchar(150) DEFAULT NULL,
  `body_bn` longtext NOT NULL,
  `body_en` longtext DEFAULT NULL,
  `is_published` tinyint(1) NOT NULL DEFAULT 0,
  `in_menu` tinyint(1) NOT NULL DEFAULT 0,
  `menu_order` smallint(6) NOT NULL DEFAULT 100,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pages_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `personal_access_tokens`;
CREATE TABLE `personal_access_tokens` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tokenable_type` varchar(255) NOT NULL,
  `tokenable_id` bigint(20) unsigned NOT NULL,
  `name` text NOT NULL,
  `token` varchar(64) NOT NULL,
  `abilities` text DEFAULT NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `personal_access_tokens_token_unique` (`token`),
  KEY `personal_access_tokens_tokenable_type_tokenable_id_index` (`tokenable_type`,`tokenable_id`),
  KEY `personal_access_tokens_expires_at_index` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `push_tokens`;
CREATE TABLE `push_tokens` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `token` varchar(500) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `push_tokens_token_unique` (`token`),
  KEY `push_tokens_user_id_index` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reports`;
CREATE TABLE `reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `public_id` char(26) NOT NULL,
  `issue_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `description` text NOT NULL,
  `lat` decimal(10,7) NOT NULL,
  `lng` decimal(10,7) NOT NULL,
  `moderation` enum('pending','approved','hidden') NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `suggested_area_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reports_public_id_unique` (`public_id`),
  KEY `reports_issue_id_foreign` (`issue_id`),
  KEY `reports_user_id_foreign` (`user_id`),
  KEY `reports_moderation_index` (`moderation`),
  KEY `reports_suggested_area_id_foreign` (`suggested_area_id`),
  KEY `reports_moderation_idx` (`moderation`,`created_at`),
  CONSTRAINT `reports_issue_id_foreign` FOREIGN KEY (`issue_id`) REFERENCES `issues` (`id`),
  CONSTRAINT `reports_suggested_area_id_foreign` FOREIGN KEY (`suggested_area_id`) REFERENCES `admin_areas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reports_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` varchar(255) NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `payload` longtext NOT NULL,
  `last_activity` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `key` varchar(100) NOT NULL,
  `value` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sms_gateways`;
CREATE TABLE `sms_gateways` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `channel` varchar(10) NOT NULL DEFAULT 'sms',
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `priority` int(10) unsigned NOT NULL DEFAULT 10,
  `method` varchar(4) NOT NULL DEFAULT 'GET',
  `url` varchar(500) NOT NULL,
  `body_type` varchar(10) NOT NULL DEFAULT 'query',
  `params` text DEFAULT NULL,
  `headers` text DEFAULT NULL,
  `sender_id` varchar(60) DEFAULT NULL,
  `success_marker` varchar(100) DEFAULT NULL,
  `api_key_enc` text DEFAULT NULL,
  `last_status` varchar(10) DEFAULT NULL,
  `last_note` varchar(255) DEFAULT NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `status_events`;
CREATE TABLE `status_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `issue_id` bigint(20) unsigned NOT NULL,
  `dimension` enum('progress','verification','disposition') NOT NULL,
  `from_value` varchar(30) DEFAULT NULL,
  `to_value` varchar(30) NOT NULL,
  `actor_id` bigint(20) unsigned DEFAULT NULL,
  `actor_type` enum('citizen','volunteer','moderator','authority','system') NOT NULL,
  `source_type` enum('platform','official_letter','news','public_notice','site_visit','phone_call') NOT NULL DEFAULT 'platform',
  `source_url` varchar(500) DEFAULT NULL,
  `reason` text NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `status_events_actor_id_foreign` (`actor_id`),
  KEY `status_events_issue_id_created_at_index` (`issue_id`,`created_at`),
  CONSTRAINT `status_events_actor_id_foreign` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `status_events_issue_id_foreign` FOREIGN KEY (`issue_id`) REFERENCES `issues` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `user_notifications`;
CREATE TABLE `user_notifications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `issue_id` bigint(20) unsigned DEFAULT NULL,
  `status_event_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(190) NOT NULL,
  `url` varchar(300) DEFAULT NULL,
  `read_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_notifications_user_id_index` (`user_id`),
  KEY `user_notifications_issue_id_index` (`issue_id`),
  KEY `user_notifications_created_at_index` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `public_id` char(26) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `email` varchar(190) DEFAULT NULL,
  `google_id` varchar(190) DEFAULT NULL,
  `display_name` varchar(100) DEFAULT NULL,
  `role` enum('citizen','volunteer','moderator','authority','admin') NOT NULL DEFAULT 'citizen',
  `is_banned` tinyint(1) NOT NULL DEFAULT 0,
  `phone_verified_at` timestamp NULL DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_public_id_unique` (`public_id`),
  UNIQUE KEY `users_phone_unique` (`phone`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `users_google_id_unique` (`google_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `volunteer_applications`;
CREATE TABLE `volunteer_applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `admin_area_id` bigint(20) unsigned NOT NULL,
  `message` text NOT NULL,
  `agreed_at` timestamp NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `decision_note` varchar(500) DEFAULT NULL,
  `decided_by` bigint(20) unsigned DEFAULT NULL,
  `decided_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `volunteer_applications_admin_area_id_foreign` (`admin_area_id`),
  KEY `volunteer_applications_decided_by_foreign` (`decided_by`),
  KEY `volunteer_applications_user_id_status_index` (`user_id`,`status`),
  KEY `volunteer_applications_status_index` (`status`),
  CONSTRAINT `volunteer_applications_admin_area_id_foreign` FOREIGN KEY (`admin_area_id`) REFERENCES `admin_areas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `volunteer_applications_decided_by_foreign` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `volunteer_applications_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
